import React, { useState } from 'react';

const Dashboard = ({ onNavigate }) => { 
    const [pnrInput, setPnrInput] = useState('');

    // 1. MUST UPDATE: Your current Ngrok URL
    const NGROK_URL = "https://your-ngrok-url.ngrok-free.app"; 

    // 2. MUST UPDATE: Your mobile number with country code (e.g., +91...)
    const MY_PHONE_NUMBER = "+91XXXXXXXXXX"; 

    const triggerVoiceCall = async () => {
        console.log("Button clicked. Attempting call to:", MY_PHONE_NUMBER);
        try {
            const response = await fetch(`${NGROK_URL}/make-call`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ to: MY_PHONE_NUMBER }) 
            });

            if (response.ok) {
                alert("Call initiated to " + MY_PHONE_NUMBER); // Success message
            } else {
                const errData = await response.json();
                alert("Twilio Error: " + errData.message);
            }
        } catch (err) {
            console.error("Connection Error:", err);
            alert("Connection error. Is your server and ngrok running?");
        }
    };

    return (
        <div style={{ background: '#070b14', height: '100vh', display: 'flex', color: '#e2e8f0', fontFamily: 'serif', overflow: 'hidden' }}>

            {/* LEFT SECTION: AMENITIES & VOICE BUTTONS */}
            <div style={{ width: '280px', borderRight: '1px solid #1e293b', display: 'flex', flexDirection: 'column', padding: '20px' }}>
                <h3 style={{ color: '#3b82f6', fontSize: '12px', letterSpacing: '2px', marginBottom: '20px' }}>AIRPORT AMENITIES</h3>
                <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                    {["Duty Free Luxe", "Hamleys Toys", "Starbucks Reserve", "Reliance Digital", "Plaza Lounge", "Global Food Court", "Medical Center", "ATM / Currency"].map(item => (
                        <div key={item} style={{ background: '#111827', padding: '12px', borderRadius: '8px', fontSize: '11px', border: '1px solid #1e293b' }}>{item}</div>
                    ))}
                </div>

                <div style={{ marginTop: 'auto', display: 'flex', flexDirection: 'column', gap: '10px' }}>
                    {/* CRITICAL: Ensure onClick={triggerVoiceCall} is present */}
                    <button 
                        onClick={triggerVoiceCall} 
                        style={{ background: '#2563eb', color: 'white', padding: '15px', borderRadius: '10px', border: 'none', cursor: 'pointer', fontWeight: 'bold' }}
                    >
                        📞 START VOICE CALL
                    </button>
                    <button 
                        onClick={() => onNavigate('voiceweb')} 
                        style={{ background: '#1e3a8a', color: 'white', padding: '15px', borderRadius: '10px', border: 'none', cursor: 'pointer', fontWeight: 'bold' }}
                    >
                        🌐 START VOICE WEB
                    </button>
                </div>
            </div>

            {/* CENTER SECTION: WELCOME & RADAR */}
            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', padding: '40px' }}>
                <h1 style={{ letterSpacing: '10px', fontSize: '48px', margin: '0', color: '#3b82f6' }}>SKY-SYNC AI</h1>
                <p style={{ opacity: 0.5, marginBottom: '40px' }}>INTELLIGENT FLIGHT OPERATIONAL SYSTEM</p>

                <div style={{ width: '80%', display: 'flex', gap: '10px', marginBottom: '40px' }}>
                    <input 
                        type="text" 
                        placeholder="ENTER PNR NUMBER..." 
                        value={pnrInput}
                        onChange={(e) => setPnrInput(e.target.value.toUpperCase())}
                        style={{ flex: 1, background: '#111827', border: '1px solid #3b82f6', padding: '15px', borderRadius: '10px', color: 'white', outline: 'none' }}
                    />
                    <button 
                        onClick={() => onNavigate('pnr-tracking', pnrInput)} 
                        style={{ background: '#3b82f6', color: 'white', padding: '0 30px', borderRadius: '10px', border: 'none', cursor: 'pointer', fontWeight: 'bold' }}
                    >
                        TRACK STATUS
                    </button>
                </div>

                <div style={{ width: '90%', flex: 1, background: '#111827', borderRadius: '15px', border: '1px solid #1e293b', overflow: 'hidden', display: 'flex', flexDirection: 'column' }}>
                    <div style={{ padding: '15px', borderBottom: '1px solid #1e293b', color: '#60a5fa', fontSize: '12px', fontWeight: 'bold' }}>LIVE FLIGHT RADAR</div>
                    <div style={{ overflowY: 'auto', flex: 1, padding: '10px' }}>
                        {[...Array(20)].map((_, i) => (
                            <div key={i} style={{ display: 'flex', justifyContent: 'space-between', padding: '12px', borderBottom: '1px solid #0f172a', fontSize: '13px' }}>
                                <span>AI-{100 + i} BOM ➔ LHR</span>
                                <span style={{ color: i % 4 === 0 ? '#ef4444' : '#22c55e' }}>{i % 4 === 0 ? 'DELAY' : 'ON TIME'}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* RIGHT SECTION: CLOCKS & NOTIFICATIONS */}
            <div style={{ width: '300px', borderLeft: '1px solid #1e293b', padding: '20px', display: 'flex', flexDirection: 'column', gap: '25px' }}>
                <div style={{ background: '#111827', padding: '20px', borderRadius: '12px', border: '1px solid #1e293b' }}>
                    <h4 style={{ color: '#60a5fa', fontSize: '11px', margin: '0 0 10px 0' }}>TEMPERATURE</h4>
                    <div style={{ fontSize: '32px' }}>28°C <span style={{ fontSize: '14px', opacity: 0.5 }}>Vijayawada</span></div>
                </div>

                <div style={{ background: '#111827', padding: '20px', borderRadius: '12px', border: '1px solid #1e293b' }}>
                    <h4 style={{ color: '#60a5fa', fontSize: '11px', margin: '0 0 10px 0' }}>WORLD CLOCKS</h4>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '8px', fontSize: '12px' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between' }}><span>New Delhi</span><span>{new Date().toLocaleTimeString()}</span></div>
                        <div style={{ display: 'flex', justifyContent: 'space-between' }}><span>New York</span><span>8:52 AM</span></div>
                        <div style={{ display: 'flex', justifyContent: 'space-between' }}><span>London</span><span>1:52 PM</span></div>
                    </div>
                </div>

                <div style={{ background: '#111827', padding: '20px', borderRadius: '12px', border: '1px solid #1e293b', flex: 1 }}>
                    <h4 style={{ color: '#60a5fa', fontSize: '11px', margin: '0 0 10px 0' }}>SYSTEM NOTIFICATIONS</h4>
                    <p style={{ fontSize: '11px', opacity: 0.6 }}>[SYS] AI Voice Engine: Ready</p>
                    <p style={{ fontSize: '11px', opacity: 0.6 }}>[SYS] Twilio Node: Connected</p>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
